let tollYesFails = 0;
async function clearDialog() {
  for (let i = 0; i < 8; i++) {
    const s = sdk.getState();
    if (!s?.dialog?.isOpen) return;
    const opts = s.dialog.options ?? [];
    if (opts.length > 1) {
      const coins = s.inventory.find((it: any) => /coins/i.test(it.name))?.count ?? 0;
      let pick = opts.find((o: any) => /^yes,? ok|^yes$/i.test(o.text));
      if (pick && coins < 10) {
        tollYesFails++;
        if (tollYesFails > 1) pick = opts.find((o: any) => /no thank|walk around/i.test(o.text)) ?? opts[0];
      }
      if (!pick) pick = opts.find((o: any) => /yes/i.test(o.text));
      if (!pick) pick = opts[0];
      console.log('dialog:', opts.map((o: any) => o.text).join(' | '), '-> pick', pick.text, 'coins', coins);
      await sdk.sendClickDialog(pick.index ?? 1);
    } else {
      await sdk.sendClickDialog(0);
    }
    await sdk.waitForTicks(2);
  }
}

